// The corpus and the window are the ones the render benchmarks already use:
// simulated alignments over a 250 kb slice of hg19 chr22 (`chr22_mask`), at 20x
// / 200x / 1000x, short reads (wgsim) and long (pbsim), regenerated by
// ../shell/generate_alignments.sh into ../data/. Reusing them means the parse
// numbers and the render numbers describe the same files.
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

export const DATA = fileURLToPath(new URL('../../data/', import.meta.url))

export const REF = 'chr22_mask'
export const START = 124_000
export const END = 143_000

export interface Case {
  label: string
  file: string
  /** records the window holds, asserted by equivalence.test.ts */
  records?: number
}

const COVERAGES = ['20x', '200x', '1000x'] as const
const KINDS = ['shortread', 'longread'] as const

function corpus(ext: string): Case[] {
  return COVERAGES.flatMap(cov =>
    KINDS.map(kind => ({
      label: `${cov} ${kind}`,
      file: `${DATA}${cov}.${kind}.${ext}`,
    })),
  )
}

export const BAM_CASES = corpus('bam')
export const CRAM_CASES = corpus('cram')

// The VCF corpus is its own thing: the alignment files carry no genotypes, and
// what a VCF parser costs scales with samples x variants rather than with read
// depth. Same contig and same window (317 variants across chr22_mask:124000-
// 143000), generated by ../../shell/generate_variants.sh.
//
// Two FORMAT shapes because they take different paths through the scan. `gtonly`
// is the 1000 Genomes phase 3 shape, where GT is the only field and there is
// nothing to skip between samples; `wide` is a joint-called cohort, where GT is
// first and every other field has to be stepped over to reach the next sample.
// The second is where the 7.2.0 scan change applies and the first is where it
// deliberately does not, so reporting only one of them would misdescribe it.
export const VCF_SAMPLE_COUNTS = [100, 1000, 3000] as const
export const VCF_SHAPES = ['gtonly', 'wide'] as const

export interface VcfCase extends Case {
  samples: number
  shape: (typeof VCF_SHAPES)[number]
}

export const VCF_CASES: VcfCase[] = VCF_SHAPES.flatMap(shape =>
  VCF_SAMPLE_COUNTS.map(samples => ({
    label: `${samples} samples ${shape}`,
    file: `${DATA}variants.${samples}.${shape}.vcf`,
    samples,
    shape,
  })),
)

// The GFF3 corpus is the third of its own kind, and the one that does NOT sit
// on the shared window: a GFF3 parse scales with feature count, and 5000 genes
// do not fit in 19 kb at any plausible density. It is on its own contig
// (`gff_contig`) so that is impossible to miss. Regenerated by
// ../../shell/generate_gff3.sh.
//
// Two attribute shapes, for the same reason the VCF corpus has two FORMAT
// shapes: they take opposite paths through the parser. `rich` (~10 attributes
// a line, GENCODE-like) is where deferring column 9 is most of the parse and
// where scanning for tab offsets barely registers; `sparse` (~1.2, a bare
// feature dump) is the exact reverse. A single-shape table would misdescribe
// both changes — and did: the sparse case was break-even until tab scanning
// landed, while the rich case never needed it.
export const GFF3_GENE_COUNTS = [200, 1000, 5000] as const
export const GFF3_SHAPES = ['sparse', 'rich'] as const

export interface Gff3Case extends Case {
  genes: number
  shape: (typeof GFF3_SHAPES)[number]
}

export const GFF3_CASES: Gff3Case[] = GFF3_SHAPES.flatMap(shape =>
  GFF3_GENE_COUNTS.map(genes => ({
    label: `${genes} genes ${shape}`,
    file: `${DATA}features.${genes}.${shape}.gff3`,
    genes,
    shape,
  })),
)

/**
 * Feature lines, comments and directives dropped — what both the tabix reader
 * and the whole-file scanner hand the parser. Reading and splitting the file is
 * setup, so it happens here and not inside a timed callback.
 */
export function gff3Lines(file: string) {
  // Decoded in one pass and split, which is what the plain-text adapter does
  // (its line splitter decodes 64 KB windows). The per-line decode a tabix
  // reader would do is measured elsewhere and is not what this benchmark is
  // about, so feeding flat strings keeps the number on the parser.
  return readFileSync(file, 'utf8')
    .split('\n')
    .filter(line => line.length !== 0 && line.charCodeAt(0) !== 35 /* # */)
}

/**
 * Header text and data lines, split apart the way an indexed reader hands them
 * over: the header once at open, the lines per query. Reading and splitting the
 * file is setup, so it happens here and not inside a timed callback.
 */
export function vcfParts(file: string) {
  // Decoded per line from its own byte range, which is what
  // TabixIndexedFile.getLines does — it finds each line in the inflated buffer
  // and calls TextDecoder.decode on that subarray. The alternative, splitting
  // one big decoded string on '\n', hands the parser V8 SlicedStrings of the
  // whole file instead of flat ones, and reading a SlicedString with charCodeAt
  // costs an extra unwrap per character. Since that exact distinction is half of
  // what changed in 7.2.0, feeding it an input no real reader produces would
  // move the result for a reason that is about the harness. Decoding is also
  // cheap enough not to matter here: ~3.9 GB/s, against a scan measured in tens
  // of ms for tens of MB.
  const bytes = readFileSync(file)
  const decoder = new TextDecoder()
  const headerLines: string[] = []
  const lines: string[] = []
  let start = 0
  for (let i = 0; i <= bytes.length; i++) {
    if (i === bytes.length || bytes[i] === 10) {
      if (i > start) {
        const line = decoder.decode(bytes.subarray(start, i))
        if (line.charCodeAt(0) === 35 /* # */) {
          headerLines.push(line)
        } else {
          lines.push(line)
        }
      }
      start = i + 1
    }
  }
  if (!headerLines.some(l => l.startsWith('#CHROM'))) {
    throw new Error(`${file}: no #CHROM line`)
  }
  return { header: `${headerLines.join('\n')}\n`, lines }
}

// hg19mod.fa is one contig, so the whole reference is small enough to hold as a
// string and answer seqFetch from memory. Doing it here rather than through an
// indexed-fasta reader keeps a second library out of the CRAM measurement.
let refSeq: string | undefined

export function reference(): string {
  if (refSeq === undefined) {
    const text = readFileSync(`${DATA}hg19mod.fa`, 'utf8')
    refSeq = text.slice(text.indexOf('\n') + 1).replaceAll('\n', '')
  }
  return refSeq
}

/** CRAM's seqFetch contract is 1-based and inclusive on both ends. */
export const seqFetch = async (_seqId: number, start: number, end: number) =>
  reference().slice(start - 1, end)

// cram-js v1.7.3 defaults fetchSizeLimit to 3 MB and throws past it, which every
// long-read window here exceeds. JBrowse 2 never ran that default: its
// CramAdapter set `fetchSizeLimit: 200_000_000` with the comment "just make this
// a large size to avoid hitting it". Passing the same value reproduces what
// JBrowse actually ran rather than a limit no user of it ever hit. The current
// release has no such limit, so this option applies only to the old side.
export const OLD_CRAM_OPTS = { fetchSizeLimit: 200_000_000 }

export function bytes(file: string) {
  return readFileSync(file).byteLength
}
